// Localize seed data strings so zero English helper words remain in non-English routes
function localizeSeedField(raw: string, locale: LocaleCode): string {
  if (locale === 'en') return raw;
  const isIt = locale === 'it';
  return raw
    .replace(/Open 7\/7 Mon–Sun/g, isIt ? 'Aperto 7/7 Lun–Dom' : '7/7')
    .replace(/Open 7\/7/g, isIt ? 'Aperto 7/7' : '7/7')
    .replace(/Women/g, isIt ? 'Donne' : 'F')
    .replace(/Men/g, isIt ? 'Uomini' : 'M')
    .replace(/up to /g, isIt ? 'fino a ' : '')
    .replace(/guests/g, isIt ? 'ospiti' : 'pax')
    .replace(/100% bottle credit/g, isIt ? '100% credito bottiglie' : '100% VIP')
    .replace(/Accredited Guestlist/g, isIt ? 'Lista Accreditata' : 'VIP Guestlist')
    .replace(/Seated Dinner/g, isIt ? 'Cena Servita' : 'Dinner Show')
    .replace(/walk/g, isIt ? 'a piedi' : '')
    .replace(/guarded parking/gi, isIt ? 'parcheggio custodito' : 'Parking 24/7')
    .replace(/guarded garage/gi, isIt ? 'garage custodito' : 'Garage 24/7')
    .replace(/right outside/gi, isIt ? 'all’ingresso' : '')
    .replace(/elevated Privé/gi, isIt ? 'Privé rialzato' : 'Privé VIP')
    .replace(/person/g, isIt ? 'persona' : 'pax');
}

