const RENDER_CACHE = new Map<string, ReturnType<typeof renderEnGuide>>();

function getRenderedGuideForLocale(seed: GuideSeed100, locale: LocaleCode) {
  const key = `${seed.id}:${locale}`;
  const cached = RENDER_CACHE.get(key);
  if (cached) return cached;
  let rendered: ReturnType<typeof renderEnGuide>;
  if (locale === 'en') {
    rendered = renderEnGuide(seed);
  } else if (locale === 'it') {
    rendered = renderItGuide(seed);
  } else {
    const dict = COMPACT_33_DICTS[locale] || COMPACT_33_DICTS.es;
    rendered = renderCompactGuide(seed, locale, dict);
  }
  RENDER_CACHE.set(key, rendered);
  return rendered;
}

function createLazyLocalizedString(getter: (locale: LocaleCode) => string): LocalizedString {
  const obj = {} as LocalizedString;
  for (const loc of ALL_35_LOCALES) {
    Object.defineProperty(obj, loc, {
      enumerable: true,
      configurable: true,
      get() {
        return getter(loc);
      },
    });
  }
  return obj;
}

function buildGuideFromSeed(seed: GuideSeed100): Guide {
  const sections: GuideSection[] = [0, 1, 2, 3, 4].map((idx) => ({
    id: `${seed.id}-sec-${idx + 1}`,
    heading: createLazyLocalizedString((loc) => getRenderedGuideForLocale(seed, loc).sections[idx].h),
    content: createLazyLocalizedString((loc) => getRenderedGuideForLocale(seed, loc).sections[idx].b),
  }));

  const faqs: FAQ[] = [0, 1, 2, 3, 4, 5].map((idx) => ({
    question: createLazyLocalizedString((loc) => getRenderedGuideForLocale(seed, loc).faqs[idx].q),
    answer: createLazyLocalizedString((loc) => getRenderedGuideForLocale(seed, loc).faqs[idx].a),
  }));

  const defaultGenres: MusicGenre[] = [
    MusicGenre.HOUSE,
    MusicGenre.COMMERCIAL,
    MusicGenre.HIP_HOP,
    MusicGenre.REGGAETON,
  ];

  return {
    id: seed.id,
    slugs: { ...seed.slugs35 },
    title: createLazyLocalizedString((loc) => getRenderedGuideForLocale(seed, loc).title),
    excerpt: createLazyLocalizedString((loc) => getRenderedGuideForLocale(seed, loc).excerpt),
    image: seed.image,
    sections,
    faqs,
    relatedGenres: defaultGenres,
    author: 'Nightlife Milan Official Concierge (+39 351 912 7047)',
    datePublished: '2026-10-01',
    dateModified: '2026-11-06',
  };
}

export const EXTRA_100_GUIDES: Guide[] = GUIDE_100_SEEDS.map(buildGuideFromSeed);

export const GUIDE_100_HERO_IMAGES: Record<string, string> = Object.fromEntries(
  GUIDE_100_SEEDS.map((s) => [s.id, s.image])
);

export const GUIDE_100_INLINE_IMAGES: Record<string, string[]> = Object.fromEntries(
  GUIDE_100_SEEDS.map((s) => [s.id, s.inlineImages])
);

export const GUIDE_100_RELATED_VENUES: Record<string, string[]> = Object.fromEntries(
  GUIDE_100_SEEDS.map((s) => [s.id, s.relatedVenues])
);

const SEED_BY_ID = new Map<string, GuideSeed100>(GUIDE_100_SEEDS.map((s) => [s.id, s]));
registerExtraGuideSlugs35(GUIDE_100_SEEDS);

/**
 * Ensures guide.slugs is populated for all 35 languages (both for the 14 existing guides in mockGuides
 * and for the 100 new guides in EXTRA_100_GUIDES) and returns the localized slug for the requested locale.
 */
export function getLocalizedGuideSlug35(guide: Guide, locale: LocaleCode): string {
  const existing14 = EXISTING_14_GUIDE_SLUGS_35[guide.id];
  if (existing14) {
    if (!guide.slugs || Object.keys(guide.slugs).length < 35) {
      guide.slugs = { ...existing14, ...(guide.slugs || {}) };
    }
    return guide.slugs[locale] || existing14[locale] || guide.slugs.en;
  }

  const seed100 = SEED_BY_ID.get(guide.id);
  if (seed100) {
    if (!guide.slugs || Object.keys(guide.slugs).length < 35) {
      guide.slugs = { ...seed100.slugs35, ...(guide.slugs || {}) };
    }
    return guide.slugs[locale] || seed100.slugs35[locale] || guide.slugs.en;
  }

  return guide.slugs?.[locale] || guide.slugs?.en || guide.id;
}

/**
 * Populates guide.slugs across all 35 languages in-place for an array of guides (e.g. mockGuides + EXTRA_100_GUIDES).
 */
export function populateGuideSlugs35(guides: Guide[]): Guide[] {
  for (const g of guides) {
    getLocalizedGuideSlug35(g, 'en');
  }
  return guides;
}

/**
 * Resolves any 35-language guide slug back to its Guide object.
 */
export function resolveGuideBySlug35(slug: string, allGuides?: Guide[]): Guide | undefined {
  const list = allGuides || EXTRA_100_GUIDES;
  populateGuideSlugs35(list);
  return list.find(
    (g) => g.slugs && Object.values(g.slugs).includes(slug)
  );
}
